fury_prepare_random_event_fire = {
	set_temp_variable = { fury_prefire_created_actor = 0 }
	set_temp_variable = { fury_prefire_existing_actor_count = 0 }
	every_country = {
		limit = { is_fury_actor = yes }
		add_to_temp_variable = { fury_prefire_existing_actor_count = 1 }
	}
	fury_sync_evolution_unlocks = yes
	if = {
		limit = { any_country = { fury_can_be_selected = yes } }
		fury_select_ordinary_actor = yes
	}
	if = {
		limit = { check_variable = { fury_prefire_created_actor > 0 } }
		if = {
			limit = { has_global_flag = fury_evolution_iii_unlocked }
			fury_ensure_actor_count_three = yes
		}
		else_if = {
			limit = { has_global_flag = fury_evolution_ii_unlocked }
			fury_ensure_actor_count_two = yes
		}
		set_temp_variable = { fury_prefire_new_actor_count = 0 }
		every_country = {
			limit = { is_fury_actor = yes }
			add_to_temp_variable = { fury_prefire_new_actor_count = 1 }
		}
		subtract_from_temp_variable = { fury_prefire_new_actor_count = fury_prefire_existing_actor_count }
		event_target:fury_entry_primary_actor = {
			set_variable = { fury_opening_actor_count = fury_prefire_new_actor_count }
			save_global_event_target_as = fury_latest_actor
			save_event_target_as = fury_opening_news_actor
			news_event = { id = chaosx.news.7008 }
		}
	}
	else = {
		set_temp_variable = { event_single_fire_allowed = 0 }
		fury_report_failed_manual_request = yes
	}
}
